Linear LDA gives 95.7% on my folds. Next I test nonlinear stacks: l1 is whitened PCA directions through silu, l2 is either one-vs-one discriminants or whitened PCA of l1, and l3 is LDA on l2.

```python
src2 = r'''
def fit(Xt,yt,g=1.0,b0=0.0,mode="ovo",g2=1.0,b2=0.0,s1=0.02,s3=0.02):
    m,V,v=pca(Xt,48)
    W1=g*(V/np.sqrt(v)).T; B1=-W1@m+b0
    F1=silu(Xt@W1.T+B1)
    if mode=="ovo":
        mu,S=stats(F1,yt,s1); W=[];B=[]
        for a in range(10):
            for c in range(a+1,10):
                w=np.linalg.solve(S,mu[a]-mu[c]); w=w/np.sqrt(w@S@w)
                W.append(g2*w); B.append(-g2*w@(mu[a]+mu[c])/2+b2)
        P,b=lda(F1,yt,s1)
        for i in range(3):
            w=P[i]-P.mean(0); w=w/np.sqrt(w@S@w); W.append(g2*w); B.append(-g2*w@F1.mean(0)+b2)
        W2=np.array(W);B2=np.array(B)
    else:
        m2,V2,v2=pca(F1,48); W2=g2*(V2/np.sqrt(v2+1e-6)).T; B2=-W2@m2+b2
    F2=silu(F1@W2.T+B2)
    P,b=lda(F2,yt,s3)
    return W1,B1,W2,B2,P,b
def fwd(Xq,W):
    W1,B1,W2,B2,P,b=W
    return silu(silu(Xq@W1.T+B1)@W2.T+B2)@P.T+b
def cv(seed=0,**k):
    acc=[]
    for te in folds(len(X),seed=seed):
        tr=np.setdiff1d(np.arange(len(X)),te)
        acc.append((np.argmax(fwd(X[te],fit(X[tr],y[tr],**k)),1)==y[te]).mean())
    return round(float(np.mean(acc)),4)
'''
open("lib.py","a").write(src2)
exec(open("lib.py").read())
for mode in ["ovo","pca"]:
  for g in [0.3,0.6,1.0,1.5]:
    for b0 in [0.0,1.0]:
      print(mode,"g",g,"b0",b0,[ (g2,b2,cv(g=g,b0=b0,mode=mode,g2=g2,b2=b2)) for g2,b2 in [(0.5,0.0),(1.0,1.0),(2.0,0.0)]])
